// Fatores de risco de NEUROTOXICIDADE (Tabela 2 da AAP 2022). A IG < 38 sem já entra pela IG escolhida.
const ICT_FATORES = [
    ["alb", "Albumina < 3,0 g/dL"],
    ["hem", "Doença hemolítica isoimune (Coombs direto +), deficiência de G6PD ou outra hemólise"],
    ["sep", "Sepse"],
    ["inst", "Instabilidade clínica significativa nas últimas 24 h"]
];

const ictEstado = { ig: null, tipo: "BT", fatores: {}, subindo: false };

// Limiar na hora de vida (horas completas). Antes de 1 h usa o valor de 1 h; depois do fim da tabela, o último valor.
function ictLimiar(tab, ig, h) {
    let arr = ICT_LIMIARES[tab][ig];
    let i = Math.min(Math.max(Math.floor(h), 1), arr.length) - 1;
    return arr[i];
}

function ictTemFator() { return Object.values(ictEstado.fatores).some(Boolean); }

// Chaves das tabelas: fototerapia sem fator 35..40 (40 = ≥ 40 sem); com fator e exsanguineo 35..38 (38 = ≥ 38 sem).
function ictLimiares(h) {
    let ig = ictEstado.ig, fator = ictTemFator();
    let foto = fator ? ictLimiar("fotoCom", Math.min(ig, 38), h) : ictLimiar("fotoSem", ig, h);
    let ext = (fator || ictEstado.subindo) ? ictLimiar("extCom", Math.min(ig, 38), h) : ictLimiar("extSem", Math.min(ig, 38), h);
    return { foto, ext, esc: Math.round((ext - 2) * 10) / 10 };
}

function ictNum(id) {
    let el = document.getElementById(id);
    if (!el || el.value === "") return null;
    let v = parseFloat(String(el.value).replace(",", "."));
    return isNaN(v) ? null : v;
}

function fmtIct(x) { return (Math.round(x * 10) / 10).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }); }

// Chamada pela seção da conduta (campo "ferramenta").
function ferramentaIctericia() {
    let igs = [35, 36, 37, 38, 39, 40].map(g =>
        `<button type="button" class="qm-faixa${ictEstado.ig === g ? ' ativa' : ''}" data-ig="${g}" onclick="ictEscolherIG(${g})">${g === 40 ? '≥ 40' : g} sem</button>`).join('');
    let tipos = [["BT", "BT sérica"], ["BTc", "Transcutânea (BTc)"]].map(([k, t]) =>
        `<button type="button" class="qm-faixa${ictEstado.tipo === k ? ' ativa' : ''}" data-tipo="${k}" onclick="ictEscolherTipo('${k}')">${t}</button>`).join('');
    let fatores = ICT_FATORES.map(([k, t]) =>
        `<button type="button" class="escore-opcao ict-fator${ictEstado.fatores[k] ? ' marcado' : ''}" data-fator="${k}" onclick="ictTrocarFator('${k}')"><span class="escore-pts">${ictEstado.fatores[k] ? '✓' : ''}</span>${t}</button>`).join('');
    setTimeout(atualizarIctericia, 0);
    return `<div class="ict" id="ict">
        <div class="escore-instrucao">👆 Preencha a idade gestacional, as horas de vida e a bilirrubina total. Marque os fatores de risco de neurotoxicidade presentes.</div>
        <div class="ict-rotulo">Idade gestacional (semanas completas)</div>
        <div class="qm-faixas">${igs}</div>
        <div class="ict-campos">
            <label class="ict-campo"><span>Horas de vida</span><input type="number" inputmode="decimal" min="0" step="1" id="ictHoras" placeholder="ex.: 36" oninput="atualizarIctericia()"></label>
            <label class="ict-campo"><span>Bilirrubina total (mg/dL)</span><input type="number" inputmode="decimal" min="0" step="0.1" id="ictBT" placeholder="ex.: 14,2" oninput="atualizarIctericia()"></label>
        </div>
        <details class="ict-datas"><summary>Calcular as horas pela data e hora do nascimento</summary>
            <div class="ict-campos">
                <label class="ict-campo"><span>Nascimento</span><input type="datetime-local" id="ictNasc" oninput="ictHorasPelasDatas()"></label>
                <label class="ict-campo"><span>Coleta do exame</span><input type="datetime-local" id="ictColeta" oninput="ictHorasPelasDatas()"></label>
            </div>
        </details>
        <div class="ict-rotulo">Tipo de medida</div>
        <div class="qm-faixas">${tipos}</div>
        <div class="ict-rotulo">Fatores de risco de neurotoxicidade (além da IG)</div>
        <div class="escore-opcoes ict-fatores">${fatores}</div>
        <label class="ict-check"><input type="checkbox" id="ictSubindo" ${ictEstado.subindo ? 'checked' : ''} onchange="ictEstado.subindo=this.checked;atualizarIctericia()"> BT subindo apesar de fototerapia intensiva (usa a curva de exsanguineotransfusão com fator de risco)</label>
        <details class="ict-datas"><summary>Opcional: albumina e exame anterior</summary>
            <div class="ict-campos">
                <label class="ict-campo"><span>Albumina (g/dL)</span><input type="number" inputmode="decimal" min="0" step="0.1" id="ictAlb" placeholder="relação B/A" oninput="atualizarIctericia()"></label>
                <label class="ict-campo"><span>BT anterior (mg/dL)</span><input type="number" inputmode="decimal" min="0" step="0.1" id="ictBTAnt" oninput="atualizarIctericia()"></label>
                <label class="ict-campo"><span>Horas de vida no exame anterior</span><input type="number" inputmode="decimal" min="0" step="1" id="ictHAnt" oninput="atualizarIctericia()"></label>
            </div>
        </details>
        <div class="escore-resultado" id="ict-resultado"></div>
        <div class="ict-lista" id="ict-lista"></div>
        <div class="ict-grafico" id="ict-grafico"></div>
        <button type="button" class="escore-limpar" onclick="limparIctericia()">Limpar</button>
    </div>`;
}

function ictEscolherIG(g) {
    ictEstado.ig = g;
    document.querySelectorAll('#ict [data-ig]').forEach(b => b.classList.toggle('ativa', +b.dataset.ig === g));
    atualizarIctericia();
}

function ictEscolherTipo(k) {
    ictEstado.tipo = k;
    document.querySelectorAll('#ict [data-tipo]').forEach(b => b.classList.toggle('ativa', b.dataset.tipo === k));
    atualizarIctericia();
}

function ictTrocarFator(k) {
    ictEstado.fatores[k] = !ictEstado.fatores[k];
    let b = document.querySelector(`#ict [data-fator="${k}"]`);
    if (b) { b.classList.toggle('marcado', ictEstado.fatores[k]); b.querySelector('.escore-pts').textContent = ictEstado.fatores[k] ? '✓' : ''; }
    atualizarIctericia();
}

function ictHorasPelasDatas() {
    let n = document.getElementById('ictNasc')?.value, c = document.getElementById('ictColeta')?.value;
    if (!n || !c) return;
    let h = (new Date(c) - new Date(n)) / 3600000;
    if (isNaN(h) || h < 0) return;
    document.getElementById('ictHoras').value = Math.floor(h);
    atualizarIctericia();
}

function limparIctericia() {
    ictEstado.ig = null; ictEstado.tipo = "BT"; ictEstado.fatores = {}; ictEstado.subindo = false;
    let caixa = document.getElementById('ict');
    if (caixa) caixa.outerHTML = ferramentaIctericia();
}

// Seguimento na alta de quem NÃO recebeu fototerapia (Figura 7 da AAP 2022), pela diferença limiar − bilirrubina.
function ictSeguimento(dif, h) {
    if (h < 12) return "Figura 7 só vale a partir de 12 h de vida. Alta antes de 12 h: medir a bilirrubina entre 24 e 48 h de vida.";
    if (dif < 2) return h < 24
        ? "Diferença de 0,1 a 1,9 mg/dL com &lt; 24 h: <strong>adiar a alta</strong>, considerar fototerapia e medir BT em 4 a 8 h."
        : "Diferença de 0,1 a 1,9 mg/dL: medir BT em 4 a 24 h. Opções: adiar a alta e considerar fototerapia; ou alta com acompanhamento próximo (a AAP também cita fototerapia domiciliar).";
    if (dif < 3.5) return "Diferença de 2,0 a 3,4 mg/dL: BT ou BTc em 4 a 24 h, qualquer que seja a idade ou o horário da alta.";
    if (dif < 5.5) return "Diferença de 3,5 a 5,4 mg/dL: BT ou BTc em 1 a 2 dias.";
    if (dif < 7) return "Diferença de 5,5 a 6,9 mg/dL: alta com &lt; 72 h → consulta em até 2 dias (BTc ou BT conforme julgamento clínico); alta com ≥ 72 h → julgamento clínico.";
    return "Diferença ≥ 7,0 mg/dL: alta com &lt; 72 h → consulta em até 3 dias (BTc ou BT conforme julgamento clínico); alta com ≥ 72 h → julgamento clínico.";
}

function atualizarIctericia() {
    let res = document.getElementById('ict-resultado'), lista = document.getElementById('ict-lista'), graf = document.getElementById('ict-grafico');
    if (!res) return;
    let h = ictNum('ictHoras'), bt = ictNum('ictBT'), fator = ictTemFator();
    let mostrar = (cor, num, rotulo, texto) => {
        res.style.setProperty('--cor-escore', cor);
        res.innerHTML = `<div class="escore-total"><span class="escore-total-num">${num}</span><span class="escore-total-de">mg/dL</span></div><div class="escore-classe"><strong>${rotulo}</strong><span>${texto}</span></div>`;
    };
    if (!ictEstado.ig || h === null) {
        mostrar('#64748b', '…', 'Preencha IG e horas de vida', 'O limiar aparece assim que a idade gestacional e as horas de vida forem informadas.');
        lista.innerHTML = ''; graf.innerHTML = '';
        return;
    }
    let L = ictLimiares(h), linhas = [];
    let curva = fator ? 'com fator de risco de neurotoxicidade' : 'sem fator de risco de neurotoxicidade';
    linhas.push(`Limiar de <strong>fototerapia</strong> com ${Math.floor(h)} h (${ictEstado.ig === 40 ? '≥ 40' : ictEstado.ig} sem, ${curva}): <strong>${fmtIct(L.foto)} mg/dL</strong>.`);
    linhas.push(`<strong>Escalada de cuidado</strong> a partir de <strong>${fmtIct(L.esc)} mg/dL</strong> · <strong>exsanguineotransfusão</strong> a partir de <strong>${fmtIct(L.ext)} mg/dL</strong>${(fator || ictEstado.subindo) ? ' (curva com fator de risco)' : ''}.`);

    if (bt === null) {
        mostrar('#0b5cad', fmtIct(L.foto), 'Limiar de fototerapia', 'Digite a bilirrubina para ver a conduta.');
    } else if (ictEstado.tipo === "BTc") {
        let precisaBT = bt >= 15 || bt >= L.foto - 3;
        if (precisaBT) mostrar('#d97706', fmtIct(bt), 'Colher BT sérica', `BTc ${bt >= 15 ? '≥ 15 mg/dL' : 'a 3 mg/dL ou menos do limiar (' + fmtIct(L.foto) + ')'}. A decisão de tratar é sempre pela BT sérica.`);
        else mostrar('#16a34a', fmtIct(bt), 'BTc abaixo da faixa de confirmação', `Está ${fmtIct(L.foto - bt)} mg/dL abaixo do limiar. Não precisa de BT sérica agora; seguir a Figura 7.`);
        if (!precisaBT) linhas.push(ictSeguimento(L.foto - bt, h));
    } else if (bt >= L.ext) {
        mostrar('#dc2626', fmtIct(bt), 'Exsanguineotransfusão urgente', `BT no limiar de exsanguineotransfusão (${fmtIct(L.ext)}) ou acima. Fototerapia intensiva e hidratação EV enquanto prepara.`);
    } else if (bt >= L.esc) {
        mostrar('#ea580c', fmtIct(bt), 'Escalada de cuidado', `Faltam ${fmtIct(L.ext - bt)} mg/dL para a exsanguineotransfusão. Exames STAT, fototerapia intensiva, hidratação EV, BT a cada 2 h, neonatologista/UTI.`);
    } else if (bt >= L.foto) {
        mostrar('#d97706', fmtIct(bt), 'Fototerapia intensiva indicada', `${fmtIct(bt - L.foto)} mg/dL acima do limiar (${fmtIct(L.foto)}). BT de controle em até 12 h.`);
        linhas.push(`Se iniciar agora, a suspensão é uma opção quando a BT cair a <strong>${fmtIct(L.foto - 2)} mg/dL ou menos</strong> (2 mg/dL abaixo do limiar no início). Considerar mais tempo se IG &lt; 38 sem, início &lt; 48 h ou doença hemolítica.`);
        if (h < 24) linhas.push("⚠️ BT acima do limiar com &lt; 24 h: provável <strong>doença hemolítica</strong>. Tipagem, Coombs direto, hemograma; G6PD se causa desconhecida.");
    } else {
        let dif = L.foto - bt;
        mostrar('#16a34a', fmtIct(bt), 'Sem indicação de fototerapia', `${fmtIct(dif)} mg/dL abaixo do limiar (${fmtIct(L.foto)}).`);
        linhas.push(`<strong>Seguimento na alta</strong> (sem fototerapia): ${ictSeguimento(dif, h)}`);
    }

    // Velocidade de aumento (KAS 7): ≥ 0,3 mg/dL/h nas primeiras 24 h ou ≥ 0,2 mg/dL/h depois sugere hemólise.
    let btAnt = ictNum('ictBTAnt'), hAnt = ictNum('ictHAnt');
    if (bt !== null && btAnt !== null && hAnt !== null && h > hAnt) {
        let vel = (bt - btAnt) / (h - hAnt), corte = h <= 24 ? 0.3 : 0.2;
        linhas.push(`Velocidade de aumento: <strong>${vel.toLocaleString('pt-BR', { maximumFractionDigits: 2 })} mg/dL/h</strong>${vel >= corte ? ` — ⚠️ ≥ ${String(corte).replace('.', ',')} mg/dL/h sugere <strong>hemólise</strong>: pedir Coombs direto se ainda não feito.` : ' (sem aumento rápido).'}`);
    }
    // Relação bilirrubina/albumina (só apoio à decisão de exsanguineotransfusão)
    let alb = ictNum('ictAlb');
    if (bt !== null && alb) {
        let ra = bt / alb, corteBA = ictEstado.ig >= 38 ? (fator ? 7.2 : 8.0) : (fator ? 6.8 : 7.2);
        linhas.push(`Relação B/A: <strong>${fmtIct(ra)}</strong> (corte para considerar exsanguineotransfusão: ${String(corteBA).replace('.', ',')})${ra >= corteBA ? ' — <strong>no corte ou acima</strong>.' : '.'}${alb < 3 && !ictEstado.fatores.alb ? ' Albumina &lt; 3,0: marque o fator de risco acima.' : ''}`);
    }
    if (ictEstado.ig < 38) linhas.push("IG &lt; 38 semanas já é fator de risco de neurotoxicidade: está embutida na curva da IG.");
    lista.innerHTML = `<ul>${linhas.map(l => `<li>${l}</li>`).join('')}</ul>`;
    graf.innerHTML = ictSvgGrafico(h, bt, btAnt, hAnt);
}

// Gráfico: curvas de fototerapia, escalada e exsanguineotransfusão da IG escolhida, com o ponto do paciente.
function ictSvgGrafico(h, bt, btAnt, hAnt) {
    let W = 360, H = 240, ml = 30, mr = 8, mt = 10, mb = 30;
    let xmax = h > 156 ? 336 : 168, ymax = 30;
    let x = t => ml + (t / xmax) * (W - ml - mr), y = v => mt + (1 - v / ymax) * (H - mt - mb);
    let caminho = fn => { let p = []; for (let t = 1; t <= xmax; t += (xmax > 168 ? 2 : 1)) p.push(`${x(t).toFixed(1)},${y(fn(t)).toFixed(1)}`); return 'M' + p.join('L'); };
    let grade = '';
    for (let v = 0; v <= ymax; v += 5) grade += `<line x1="${ml}" x2="${W - mr}" y1="${y(v)}" y2="${y(v)}" class="ict-g-grade"/><text x="${ml - 4}" y="${y(v) + 3}" text-anchor="end" class="ict-g-txt">${v}</text>`;
    let passo = xmax > 168 ? 48 : 24;
    for (let t = 0; t <= xmax; t += passo) grade += `<line x1="${x(t)}" x2="${x(t)}" y1="${mt}" y2="${H - mb}" class="ict-g-grade"/><text x="${x(t)}" y="${H - mb + 12}" text-anchor="middle" class="ict-g-txt">${t}</text>`;
    let pontos = '';
    if (btAnt !== null && hAnt !== null && hAnt <= xmax) pontos += `<circle cx="${x(hAnt)}" cy="${y(Math.min(btAnt, ymax))}" r="4" class="ict-g-ant"/>`;
    if (bt !== null && h <= xmax) pontos += `<circle cx="${x(h)}" cy="${y(Math.min(bt, ymax))}" r="6" class="ict-g-pac"/>`;
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de limiares de bilirrubina">
        ${grade}
        <path d="${caminho(t => ictLimiares(t).ext)}" class="ict-g-ext"/>
        <path d="${caminho(t => ictLimiares(t).esc)}" class="ict-g-esc"/>
        <path d="${caminho(t => ictLimiares(t).foto)}" class="ict-g-foto"/>
        ${pontos}
        <text x="${(W + ml) / 2}" y="${H - 4}" text-anchor="middle" class="ict-g-txt">horas de vida</text>
    </svg>
    <div class="ict-g-legenda"><span class="ict-l ict-l-foto"></span>Fototerapia <span class="ict-l ict-l-esc"></span>Escalada <span class="ict-l ict-l-ext"></span>Exsanguineo <span class="ict-l ict-l-pac"></span>Paciente</div>`;
}

